 */
document.addEventListener('DOMContentLoaded', () => {
    const searchButton = document.querySelector('.icon-button[aria-label="Search products"]');
    if (searchButton) {
        searchButton.addEventListener('click', () => {
            announceMessage('Search functionality would open here');
            showToast('Search feature coming soon');
        });
    }

    // Cart button
    const cartButton = document.querySelector('.icon-button[aria-label="Shopping cart"]');
    if (cartButton) {
        cartButton.addEventListener('click', () => {
            if (cartItems.length === 0) {
                announceMessage('Your cart is empty');
                showToast('Cart is empty');
            } else {
                announceMessage(`Your cart contains ${cartItems.length} items`);
                showToast(`Cart: ${cartItems.length} item${cartItems.length > 1 ? 's' : ''}`);
            }
        });
    }

    // Account button
    const accountButton = document.querySelector('.icon-button[aria-label="User account"]');
    if (accountButton) {
        accountButton.addEventListener('click', () => {
            announceMessage('Account functionality would open here');
            showToast('Login/Account feature coming soon');
        });
    }

    // Initialize cart badge
    updateCartBadge();

    // Setup keyboard shortcuts
    setupKeyboardShortcuts();
});

// ============================================================================
// Keyboard Shortcuts
// ============================================================================

/**
 * Setup keyboard shortcuts for better accessibility
 */
function setupKeyboardShortcuts() {
    document.addEventListener('keydown', (e) => {
        // Alt+H: Home/Hero section
        if (e.altKey && e.key === 'h') {
            const hero = document.querySelector('.hero');
            if (hero) {
                hero.scrollIntoView({ behavior: 'smooth' });
                hero.focus();
            }
        }

        // Alt+P: Products section
        if (e.altKey && e.key === 'p') {
            const products = document.querySelector('.products-section');
            if (products) {
                products.scrollIntoView({ behavior: 'smooth' });
                const heading = products.querySelector('h2');
                if (heading) heading.focus();
            }
        }

        // Alt+D: Deals section
        if (e.altKey && e.key === 'd') {
            const deals = document.querySelector('.deals-section');
            if (deals) {
                deals.scrollIntoView({ behavior: 'smooth' });
                const heading = deals.querySelector('h2');
                if (heading) heading.focus();
            }
        }

        // Alt+N: Newsletter section
        if (e.altKey && e.key === 'n') {
            const newsletter = document.querySelector('.newsletter-section');
            if (newsletter) {
                newsletter.scrollIntoView({ behavior: 'smooth' });
                const input = newsletter.querySelector('.newsletter-input');
                if (input) input.focus();
            }
        }
    });
}

// ============================================================================
// Form Validation
// ============================================================================

/**
 * Setup real-time email validation for newsletter
 */
document.addEventListener('DOMContentLoaded', () => {
    const emailInput = document.getElementById('email-input');
    if (emailInput) {
        emailInput.addEventListener('input', () => {
            if (emailInput.value && !isValidEmail(emailInput.value)) {
                emailInput.setAttribute('aria-invalid', 'true');
            } else {
                emailInput.setAttribute('aria-invalid', 'false');
            }
        });

        emailInput.addEventListener('blur', () => {
            if (emailInput.value && !isValidEmail(emailInput.value)) {
                emailInput.setAttribute('aria-invalid', 'true');
            }
        });
    }
});

// ============================================================================
// Analytics and Logging (for demonstration)
// ============================================================================

/**
 * Log page analytics
 */
window.addEventListener('load', () => {
    console.log('StyleHub homepage loaded successfully');
    console.log('Keyboard shortcuts available:');
    console.log('  Alt+H - Navigate to hero section');
    console.log('  Alt+P - Navigate to products section');
    console.log('  Alt+D - Navigate to deals section');
    console.log('  Alt+N - Navigate to newsletter section');
});

/**
 * Track product interactions
 */
function trackProductInteraction(productName, action) {
    console.log(`Product interaction: ${productName} - ${action}`);
}

/**
 * Make trackProductInteraction available for inline handlers if needed
 */
window.trackProductInteraction = trackProductInteraction;
