    transition: color 0.2s ease;
    display: inline-block;
    padding: 8px;
    border-radius: 4px;
}

.nav-link:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

/* ============================================================================
   Main Layout
   ============================================================================ */

.section-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
}

/* ============================================================================
   Hero Section
   ============================================================================ */

.hero {
    background: linear-gradient(135deg, #ecf0f1 0%, #bdc3c7 100%);
    padding: 4rem 2rem;
    display: flex;
    align-items: center;
    gap: 2rem;
    min-height: 500px;
    max-width: 100%;
}

.hero-content {
    flex: 1;
    color: #2c3e50;
}

.hero-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.hero-content p {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
    color: #555;
}

.hero-image {
    flex: 1;
    max-width: 500px;
    height: auto;
    border-radius: 8px;
    object-fit: cover;
}

@media (max-width: 768px) {
    .hero {
        flex-direction: column;
        padding: 2rem;
        min-height: auto;
    }

    .hero-content h2 {
        font-size: 1.75rem;
    }

    .hero-image {
        max-width: 100%;
        width: 100%;
    }
}

/* ============================================================================
   Products Section
   ============================================================================ */

.products-section {
    padding: 4rem 0;
    background-color: #fafafa;
}

.products-section h2 {
    text-align: center;
    margin-bottom: 0.5rem;
}

.section-subtitle {
    text-align: center;
    color: #7f8c8d;
    font-size: 1.1rem;
    margin-bottom: 2rem;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.product-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.product-card:focus-within {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.product-image-wrapper {
    position: relative;
    overflow: hidden;
    background-color: #ecf0f1;
    aspect-ratio: 1;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: #3498db;
    color: #fff;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
}

.product-badge.sale-badge {
    background-color: #e74c3c;
}

.product-info {
    padding: 1.5rem;
}

.product-name {
    margin-bottom: 0.25rem;
    font-size: 1.1rem;
}

.product-category {
    color: #7f8c8d;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.product-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.stars {
    color: #f39c12;
    font-size: 0.9rem;
}

.rating-count {
    color: #95a5a6;
    font-size: 0.85rem;
}

.product-pricing {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.price-current {
    font-size: 1.3rem;
    font-weight: 700;
    color: #2c3e50;
}

.price-original {
    font-size: 0.95rem;
    text-decoration: line-through;
    color: #95a5a6;
}

.section-footer {
    text-align: center;
}

/* ============================================================================
   Deals Section
   ============================================================================ */

.deals-section {
    padding: 4rem 0;
    background-color: #fff;
}

.deals-section h2 {
    text-align: center;
    margin-bottom: 0.5rem;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.deal-card {
    background: linear-gradient(135deg, #f8f9fa 0%, #ecf0f1 100%);
    padding: 2rem;
    border-radius: 8px;
    border: 1px solid #ddd;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.deal-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
}

.deal-card:focus-within {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.featured-deal {
    background: linear-gradient(135deg, #3498db 0%, #2980b9 100%);
    color: #fff;
}

.featured-deal .deal-discount {
    background-color: rgba(255, 255, 255, 0.3);
    color: #fff;
}

.deal-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1rem;
}

.deal-header h3 {
    margin: 0;
    font-size: 1.2rem;
}

.deal-discount {
    background-color: #e74c3c;
    color: #fff;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
    white-space: nowrap;
}

.deal-timer {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin: 1rem 0;
    font-weight: 600;
    color: #e74c3c;
}

.featured-deal .deal-timer {
    color: #ffd700;
}

.timer-label {
    font-size: 0.9rem;
}

/* ============================================================================
   Editorial Section
   ============================================================================ */

.editorial-section {
    padding: 4rem 0;
    background-color: #fafafa;
}

.editorial-section h2 {
    text-align: center;
    margin-bottom: 0.5rem;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.editorial-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.editorial-card:focus-within {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.editorial-image {
    width: 100%;
    height: 200px;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.editorial-card:hover .editorial-image {
    transform: scale(1.05);
}

.editorial-content {
    padding: 1.5rem;
}

.editorial-category {
    display: inline-block;
    background-color: #e74c3c;
    color: #fff;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    margin-bottom: 0.75rem;
}

.editorial-title {
    margin-bottom: 0.75rem;
}

.editorial-link {
    color: #2c3e50;
    text-decoration: none;
    font-weight: 600;
}

.editorial-link:hover {
    color: #3498db;
    text-decoration: underline;
}

.editorial-excerpt {
    color: #7f8c8d;
    font-size: 0.95rem;
    margin-bottom: 1rem;
}

.editorial-date {
    display: block;
    color: #95a5a6;
    font-size: 0.85rem;
}

/* ============================================================================
   Newsletter Section
   ============================================================================ */

.newsletter-section {
    background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
    color: #fff;
    padding: 3rem 2rem;
}

.newsletter-container {
    display: grid;
    grid-template-columns: 1fr 1.5fr;
    gap: 2rem;
    align-items: center;
}

.newsletter-content h2 {
    color: #fff;
    margin-bottom: 1rem;
}

.newsletter-content p {
    color: #bdc3c7;
    margin-bottom: 0;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-input {
    flex: 1;
    padding: 12px 16px;
    border: 2px solid transparent;
    border-radius: 4px;
    font-size: 1rem;
    min-height: 44px;
}

.newsletter-input:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.newsletter-input::placeholder {
    color: #95a5a6;
}

.newsletter-privacy {
    font-size: 0.85rem;
    color: #bdc3c7;
    margin-top: 0.75rem;
}

.newsletter-privacy a {
    color: #ffd700;
}

.newsletter-privacy a:hover {
    text-decoration: underline;
}

@media (max-width: 768px) {
    .newsletter-container {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }
}

/* ============================================================================
   Footer
   ============================================================================ */

.footer {
    background-color: #1a1a1a;
    color: #bdc3c7;
    padding: 3rem 0 1rem;
}

.footer-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
    padding: 2rem;
}

.footer-section h3 {
    color: #fff;
    margin-bottom: 1rem;
    font-size: 1rem;
}

.footer-links,
.social-links {
    list-style: none;
    margin: 0;
    padding: 0;
}

.footer-links li,
.social-links li {
    margin-bottom: 0.5rem;
}

.footer-links a,
.social-links a {
    color: #bdc3c7;
    text-decoration: none;
    transition: color 0.2s ease;
}

.footer-links a:hover,
.social-links a:hover {
    color: #fff;
}

.footer-links a:focus,
.social-links a:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.footer-bottom {
    border-top: 1px solid #2c3e50;
    padding: 1.5rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #95a5a6;
    font-size: 0.9rem;
}

.legal-links {
    list-style: none;
    display: flex;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.legal-links a {
    color: #95a5a6;
}

.legal-links a:hover {
    color: #fff;
}

@media (max-width: 768px) {
    .footer-bottom {
        flex-direction: column;
        gap: 1rem;
        text-align: center;
    }

    .legal-links {
        flex-direction: column;
        gap: 0.5rem;
    }
}

/* ============================================================================
   Responsive Design
   ============================================================================ */

@media (max-width: 768px) {
    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-container {
        padding: 1rem;
        gap: 1rem;
    }

    .navigation {
        display: none;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .products-section,
    .deals-section,
    .editorial-section {
        padding: 2rem 0;
    }
}

@media (max-width: 480px) {
    .header-container {
        flex-wrap: wrap;
    }

    .button {
        padding: 10px 16px;
        font-size: 0.9rem;
    }

    .hero {
        padding: 1.5rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .footer-container {
        grid-template-columns: 1fr;
        padding: 1rem;
    }
}

/* ============================================================================
   Accessibility: High Contrast Mode
   ============================================================================ */

@media (prefers-contrast: more) {
    body {
        color: #000;
        background-color: #fff;
    }

    .button-primary {
        border: 2px solid #000;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border: 2px solid #000;
    }

    .hero {
        border: 2px solid #000;
    }
}

/* ============================================================================
   Accessibility: Reduced Motion
   ============================================================================ */

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* ============================================================================
   Focus Visible for Keyboard Navigation
   ============================================================================ */

:focus-visible {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}
