}

.button:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.button-primary {
    background-color: #2c3e50;
    color: #fff;
    border-color: #2c3e50;
}

.button-primary:hover {
    background-color: #1a1a1a;
    border-color: #1a1a1a;
}

.button-primary:active {
    transform: scale(0.98);
}

.button-secondary {
    background-color: transparent;
    color: #2c3e50;
    border-color: #2c3e50;
}

.button-secondary:hover {
    background-color: #f0f0f0;
    border-color: #2c3e50;
}

.button-secondary:active {
    transform: scale(0.98);
}

.button-outline {
    background-color: transparent;
    color: #2c3e50;
    border: 2px solid #2c3e50;
}

.button-outline:hover {
    background-color: #f0f0f0;
}

/* Icon buttons */
.icon-button {
    background: none;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    padding: 8px;
    border-radius: 4px;
    min-height: 44px;
    min-width: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    transition: background-color 0.2s ease;
}

.icon-button:hover {
    background-color: #f0f0f0;
}

.icon-button:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

