    display: flex;
    list-style: none;
    gap: 2rem;
    margin: 0;
    padding: 0;
}

.nav-link {
    font-weight: 500;
    transition: color 0.2s ease;
    display: inline-block;
    padding: 8px;
    border-radius: 4px;
}

.nav-link:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

/* ============================================================================
   Main Layout
   ============================================================================ */

.section-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
}

/* ============================================================================
   Hero Section
   ============================================================================ */

.hero {
    background: linear-gradient(135deg, #ecf0f1 0%, #bdc3c7 100%);
    padding: 4rem 2rem;
    display: flex;
    align-items: center;
    gap: 2rem;
    min-height: 500px;
    max-width: 100%;
}

.hero-content {
    flex: 1;
    color: #2c3e50;
}

.hero-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.hero-content p {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
    color: #555;
}

.hero-image {
    flex: 1;
    max-width: 500px;
    height: auto;
    border-radius: 8px;
    object-fit: cover;
}

@media (max-width: 768px) {
    .hero {
        flex-direction: column;
        padding: 2rem;
        min-height: auto;
    }

    .hero-content h2 {
        font-size: 1.75rem;
    }

    .hero-image {
        max-width: 100%;
        width: 100%;
    }
}

/* ============================================================================
   Products Section
   ============================================================================ */

.products-section {
    padding: 4rem 0;
    background-color: #fafafa;
}

.products-section h2 {
    text-align: center;
    margin-bottom: 0.5rem;
}

.section-subtitle {
    text-align: center;
    color: #7f8c8d;
    font-size: 1.1rem;
    margin-bottom: 2rem;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.product-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.product-card:focus-within {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.product-image-wrapper {
    position: relative;
    overflow: hidden;
    background-color: #ecf0f1;
    aspect-ratio: 1;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: #3498db;
    color: #fff;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
}

.product-badge.sale-badge {
    background-color: #e74c3c;
}

.product-info {
    padding: 1.5rem;
}

