.footer-links a:focus,
.social-links a:focus {
    outline: 3px solid #ffd700;
    outline-offset: 2px;
}

.footer-bottom {
    border-top: 1px solid #2c3e50;
    padding: 1.5rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #95a5a6;
    font-size: 0.9rem;
}

.legal-links {
    list-style: none;
    display: flex;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.legal-links a {
    color: #95a5a6;
}

.legal-links a:hover {
    color: #fff;
}

